const { execSync } = require('child_process');
const ALLOW = ['pwd','ls','whoami','uname','date','df','du','env','which','echo','cat','head','tail','wc','file','stat','printenv','hostname','uptime','sw_vers'];
const cmd = params.cmd;
if (!cmd) throw new Error('params.cmd required');
const tokens = cmd.trim().split(/\s+/);
const bin = tokens[0];
if (!ALLOW.includes(bin)) throw new Error('Command not in allowlist: ' + bin + ' (allowed: ' + ALLOW.join(', ') + ')');
// Reject shell metacharacters that could chain commands.
if (/[;|&`$(){}<>\\]/.test(cmd)) throw new Error('Shell metacharacters are not allowed in this safe wrapper');
const cwd = params.cwd || undefined;
const timeout = Number(params.timeout_ms ?? 10000);
let out;
try { out = execSync(cmd, { encoding: 'utf8', timeout, cwd, shell: '/bin/sh' }); }
catch (e) { return { ok: false, error: e.message, stdout: e.stdout?.toString() ?? '', stderr: e.stderr?.toString() ?? '' }; }
if (out.length > 50000) out = out.slice(0, 50000) + '\n...[truncated]';
return { ok: true, cmd, stdout: out };
